#include "gtest/gtest.h"
#include "information.hpp"
#include "distributions.hpp"
#include "test_stubs.hpp"
namespace {
// Information_Clear
// IO correctness
// Test that Clear() drops the links held by a density component without
// modifying the vectors those links point to, which belong to other modules.
TEST(Information_Clear, HandlesCorrectInput) {
  fims_info::Information<double> info;

  // The recruitment module and the expected values are owned by the test, so
  // they stay alive after Clear() releases the Information containers.
  std::shared_ptr<fims_popdy::SRBevertonHolt<double> > recruitment =
      std::make_shared<fims_popdy::SRBevertonHolt<double> >();
  recruitment->log_r.resize(2);
  recruitment->log_r[0] = 3.2;
  recruitment->log_r[1] = 4.1;
  recruitment->log_expected_recruitment.resize(2);
  recruitment->log_expected_recruitment[0] = 2.1;
  recruitment->log_expected_recruitment[1] = -1.7;
  fims::Vector<double> catch_expected(3, 1.5);

  std::shared_ptr<fims_distributions::NormalLPDF<double> > normal_re =
      std::make_shared<fims_distributions::NormalLPDF<double> >();
  normal_re->input_type = "random_effects";
  normal_re->re = &recruitment->log_r;
  normal_re->re_expected_values = &recruitment->log_expected_recruitment;
  info.density_components[1] = normal_re;

  std::shared_ptr<fims_distributions::LogNormalLPDF<double> > lognormal_data =
      std::make_shared<fims_distributions::LogNormalLPDF<double> >();
  lognormal_data->input_type = "data";
  lognormal_data->data_expected_values = &catch_expected;
  info.density_components[2] = lognormal_data;

  info.Clear();

  // Test that Clear() empties the density components.
  EXPECT_EQ(info.density_components.size(), 0);
  // Test that the density components no longer point into other modules.
  EXPECT_EQ(normal_re->re, nullptr);
  EXPECT_EQ(normal_re->re_expected_values, nullptr);
  EXPECT_EQ(lognormal_data->data_expected_values, nullptr);
  // Test that the vectors owned by other modules keep their values.
  ASSERT_EQ(recruitment->log_r.size(), 2);
  EXPECT_EQ(recruitment->log_r[0], 3.2);
  EXPECT_EQ(recruitment->log_r[1], 4.1);
  ASSERT_EQ(recruitment->log_expected_recruitment.size(), 2);
  EXPECT_EQ(recruitment->log_expected_recruitment[0], 2.1);
  EXPECT_EQ(recruitment->log_expected_recruitment[1], -1.7);
  ASSERT_EQ(catch_expected.size(), 3);
  EXPECT_EQ(catch_expected[2], 1.5);
}

// Edge handling
// Test that Clear() drops a density component link into a module that
// Information owns. That module is released before the density components are
// visited, so the link must be dropped without reading through it.
TEST(Information_Clear, HandlesLinksIntoReleasedModules) {
  fims_info::Information<double> info;

  std::shared_ptr<fims_popdy::SRBevertonHolt<double> > recruitment =
      std::make_shared<fims_popdy::SRBevertonHolt<double> >();
  recruitment->log_r.resize(2);
  info.recruitment_models[recruitment->id] = recruitment;

  std::shared_ptr<fims_distributions::NormalLPDF<double> > normal_re =
      std::make_shared<fims_distributions::NormalLPDF<double> >();
  normal_re->input_type = "random_effects";
  normal_re->re = &recruitment->log_r;
  info.density_components[1] = normal_re;

  // Information now holds the only owning reference to the recruitment module.
  std::weak_ptr<fims_popdy::SRBevertonHolt<double> > recruitment_observer =
      recruitment;
  recruitment.reset();

  info.Clear();

  // Test that the recruitment module was released by Clear().
  EXPECT_TRUE(recruitment_observer.expired());
  // Test that the density component no longer points at the released module.
  EXPECT_EQ(normal_re->re, nullptr);
}

// Test that a density component that outlives one Clear() can be cleared
// again after its prior links were already emptied.
TEST(Information_Clear, HandlesRepeatedClear) {
  fims_info::Information<double> info;

  std::shared_ptr<fims_distributions::NormalLPDF<double> > normal_prior =
      std::make_shared<fims_distributions::NormalLPDF<double> >();
  fims::Vector<double> inflection_point(1, 19.7);
  normal_prior->input_type = "prior";
  normal_prior->priors[0] = &inflection_point;
  info.density_components[1] = normal_prior;

  info.Clear();
  // Test that the prior links are released.
  EXPECT_EQ(normal_prior->priors.size(), 0);

  info.density_components[1] = normal_prior;
  info.Clear();
  // Test that a second Clear() leaves the prior links empty.
  EXPECT_EQ(normal_prior->priors.size(), 0);
  // Test that the prior parameter owned by another module keeps its value.
  EXPECT_EQ(inflection_point[0], 19.7);
}
}  // namespace
